require __DIR__.'/includes/config.php'; require __DIR__.'/includes/functions.php'; verify_csrf(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$type=$_POST['property_type']??'Home';$address=trim($_POST['address']??'');$township=trim($_POST['township']??'Elmina');
  if(!$name||!$phone||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||!$address||!in_array($type,['Home','Shop'],true))$error='Complete all fields. Password must be at least 8 characters.';
  else {try{$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO users(full_name,phone,email,password_hash,role) VALUES(?,?,?,?, 'owner')");$st->execute([$name,$phone,$email,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$st=$pdo->prepare('INSERT INTO premises(owner_id,property_type,address,township) VALUES(?,?,?,?)');$st->execute([$uid,$type,$address,$township]);$pdo->commit();$_SESSION['user']=['id'=>$uid,'full_name'=>$name,'email'=>$email,'role'=>'owner','phone'=>$phone];session_regenerate_id(true);redirect('owner/index.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not register. This email may already be in use.';}}
}
$pageTitle='Register your premise';require __DIR__.'/includes/header.php'; ?>
<div style="max-width:700px;margin:auto"><div class="card"><div class="eyebrow">01 / REGISTER YOUR PREMISE</div><h2>Create your account</h2><p class="muted">Register your home or shop to get assistance from the Elmina township coordination centre.</p><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="form-row"><div class="field"><label>Full name *</label><input name="full_name" required value="<?=e($_POST['full_name']??'')?>"></div><div class="field"><label>Phone number *</label><input name="phone" required value="<?=e($_POST['phone']??'')?>"></div><div class="field"><label>Email *</label><input type="email" name="email" required value="<?=e($_POST['email']??'')?>"></div><div class="field"><label>Password (8+ characters) *</label><input type="password" name="password" minlength="8" required></div><div class="field"><label>Premise type *</label><select name="property_type"><option>Home</option><option>Shop</option></select></div><div class="field"><label>Township *</label><input name="township" value="Elmina" required></div><div class="field" style="grid-column:1/-1"><label>Property address *</label><input name="address" required placeholder="House / unit / shop, street, Elmina"></div></div><button class="btn btn-primary btn-block">Register premise</button></form><p class="muted">Already registered? <a class="red" href="<?=BASE_URL?>/login.php">Sign in</a></p></div></div><?php require __DIR__.'/includes/footer.php';?>
